sys_ws_operation.operation_script:
(function process(request, response) {
  function countRecords(table, query) {
    var ga = new GlideAggregate(table);
    if (query) ga.addEncodedQuery(query);
    ga.addAggregate("COUNT");
    ga.query();
    ga.next();
    return parseInt(ga.getAggregate("COUNT") || "0", 10);
  }

  var STOCK = "x_2056099_indust_0_inv_stock";
  var ALERT = "x_2056099_indust_0_inv_alert";
  var QC    = "x_2056099_indust_0_qc_insp";
  var REQ   = "x_2056099_indust_0_inv_req";
  var TXN   = "x_2056099_indust_0_inv_txn";
  var BATCH = "x_2056099_indust_0_inv_batch";

  // ── KPIs ──
  var totalStock = countRecords(STOCK, "active=true");
  var lowStock = countRecords(STOCK, "active=true^available_quantityLESSTHANreorder_level");
  var openAlerts = countRecords(ALERT, "status=open");
  var pendingInspections = countRecords(QC, "status=open^ORstatus=in_progress");

  // ── Category Summaries ──
  var categoryDefs = [
    { value: "raw_materials", label: "Raw Materials" },
    { value: "mro", label: "MRO Inventory" },
    { value: "finished_goods", label: "Finished Goods" },
    { value: "safety_buffer", label: "Safety / Buffer" },
    { value: "temporary_expired", label: "Temporary / Expired" },
    { value: "quarantine_disposal", label: "Quarantine / Disposal" }
  ];
  var categories = [];
  for (var i = 0; i < categoryDefs.length; i++) {
    var cat = categoryDefs[i];
    var q = "inventory_type=" + cat.value;
    var cnt = countRecords(STOCK, q);
    var ga = new GlideAggregate(STOCK);
    ga.addEncodedQuery(q);
    ga.addAggregate("SUM", "available_quantity");
    ga.query();
    var availQty = 0;
    if (ga.next()) availQty = parseInt(ga.getAggregate("SUM", "available_quantity") || "0", 10);
    categories.push({ type: cat.value, label: cat.label, count: cnt, availableQty: availQty });
  }

  // ── Alert Summary ──
  var alerts = {
    critical: countRecords(ALERT, "severity=critical^statusNOT INresolved,dismissed"),
    high: countRecords(ALERT, "severity=high^statusNOT INresolved,dismissed"),
    open: countRecords(ALERT, "status=open"),
    expiredMaterial: countRecords(ALERT, "alert_type=expired_material^statusNOT INresolved,dismissed"),
    qualityFailure: countRecords(ALERT, "alert_type=quality_failure^statusNOT INresolved,dismissed"),
    materialShortage: countRecords(ALERT, "alert_type=material_shortage^statusNOT INresolved,dismissed")
  };

  // ── Quality Summary ──
  var quality = {
    pending: countRecords(QC, "result=pending"),
    passed: countRecords(QC, "result=passed"),
    failed: countRecords(QC, "result=failed"),
    blockedBatches: countRecords(BATCH, "status=blocked")
  };

  // ── Request Summary ──
  var requests = {
    draft: countRecords(REQ, "status=draft"),
    pendingApproval: countRecords(REQ, "status=pending_approval"),
    approved: countRecords(REQ, "status=approved"),
    inProgress: countRecords(REQ, "status=in_progress"),
    completed: countRecords(REQ, "status=completed"),
    rejected: countRecords(REQ, "status=rejected")
  };

  // ── Recent Transactions (last 10) ──
  var transactions = [];
  var gr = new GlideRecord(TXN);
  gr.orderByDesc("transaction_date");
  gr.setLimit(10);
  gr.query();
  while (gr.next()) {
    transactions.push({
      number: gr.getValue("number") || "",
      material: gr.getDisplayValue("material_product") || "",
      quantity: gr.getValue("quantity") || "0",
      transactionType: gr.getDisplayValue("transaction_type") || "",
      transactionDate: gr.getDisplayValue("transaction_date") || "",
      status: gr.getDisplayValue("status") || ""
    });
  }

  response.setBody({
    result: {
      totalStock: totalStock,
      lowStock: lowStock,
      openAlerts: openAlerts,
      pendingInspections: pendingInspections,
      categories: categories,
      alerts: alerts,
      quality: quality,
      requests: requests,
      recentTransactions: transactions
    }
  });
})(request, response);
